from admissions_records import *
def fall():return {**cycle('October / Fall 2027',[2027]),'intakes':['fall-2027']}
def pdf(url,en,ru,pages,quote):return S(url,L(en,ru),pages=pages,access='pdf-read',quote=quote)
def score(min,variant=None,sections=None,noMinimum=False):
 t={'accepted':True,'min':min,'role':'admission','variant':variant}
 if sections:t['sections']=sections
 if noMinimum:t['noMinimum']=True
 return t

record('osaka-university',[route(id='human-sciences-iudp',label=L('Human Sciences International Undergraduate Degree Program — Suita','Human Sciences International Undergraduate Degree Program — Suita'),programmeIds=['social-sciences'],applicability=fall(),english={'requirement':'required-unless-exempt','ielts':score(6.5,'IELTS Academic / IELTS Indicator'), 'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':85},{'period':'post2026','min':4.5}]},'note':L('The guide says generally no IELTS component below 6.0; this qualified wording is not treated as an unconditional section cutoff. Indicator/Home Edition applicants may be interviewed. TOEFL ITP and MyBest are not accepted.','Руководство говорит «как правило, ни одна секция IELTS ниже 6,0»; эта оговорка не превращается в безусловный секционный порог. Для Indicator/Home Edition возможно интервью. TOEFL ITP и MyBest не принимаются.'),'alternatives':L('Cambridge CAE/CPE grade C; specified GCSE, GCE, IB and other English qualifications.','Cambridge CAE/CPE оценка C; указанные GCSE, GCE, IB и другие английские квалификации.'),'waiver':L('Recent secondary/university courses taught and assessed in English with passing grades, or at least 24 months of English-using employment; additional proof may be requested.','Недавние школьные/университетские предметы на английском с положительными оценками либо минимум 24 месяца работы с английским; могут запросить дополнительные документы.')},academic={'satPolicy':'conditional','note':L('Submit university-entrance qualifications applicable to your education system: SAT/ACT/AP, IB, A levels or recognised national qualifications. SAT is not the only route; the guide’s qualification appendix must be checked.','Представьте вступительную квалификацию своей системы: SAT/ACT/AP, IB, A levels либо признанные национальные квалификации. SAT — не единственный маршрут; нужно сверить приложение квалификаций.')},sources=[pdf('https://iudp.hus.osaka-u.ac.jp/wp-content/uploads/2026/07/2027-HUS-Application-Guidelines.pdf','Osaka Human Sciences October 2027 guide','Osaka Human Sciences: руководство октября 2027',[3,5,8,11,12,13,19,20,21],'Submit official scores of any standardized academic test for university entrance that you have taken.')])], 'Identified the actual English-taught Human Sciences route and its qualified section guidance instead of a university-wide English rule.', ['Other Osaka undergraduate routes, detailed programme prerequisites and applicant qualification equivalence remain outside this reviewed route.'])

record('nagoya-university',[route(id='g30',label=L('G30 English-taught undergraduate programmes — October 2027','G30: англоязычные программы бакалавриата — октябрь 2027'),applicability=fall(),english={'requirement':'required-unless-exempt','ielts':score(6,'IELTS Academic; One Skill Retake accepted'),'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':80},{'period':'post2026','min':4}],'note':L('Home Edition and MyBest accepted; TOEFL ITP and TOEIC not accepted.','Home Edition и MyBest принимаются; TOEFL ITP и TOEIC — нет.')},'alternatives':L('Duolingo 110; CEFR C1 recorded on official transcripts. Other certificates require advance review.','Duolingo 110; CEFR C1 в официальных документах. Другие сертификаты требуют предварительного рассмотрения.'),'waiver':L('At least three consecutive English-medium education years including the final secondary year, with an official school certificate.','Минимум три последовательных года обучения на английском, включая последний школьный год, с официальным школьным подтверждением.')},academic={'satPolicy':'conditional','note':L('SAT/ACT/EJU are strongly recommended, not generally compulsory. National or standardised examinations are mandatory for eligibility categories 1b and 2; curriculum-specific qualifications and subject advice still apply.','SAT/ACT/EJU настоятельно рекомендуются, но в общем случае не обязательны. Национальные/стандартизированные экзамены обязательны для категорий допуска 1b и 2; сохраняются квалификации и рекомендации предметов своей системы.')},sources=[pdf('https://admissions.g30.nagoya-u.ac.jp/upload/2027_admission_requirements_en.pdf','Nagoya G30 undergraduate AY2027 guide','Nagoya G30: руководство бакалавриата AY2027',[3,6,19,20,30,32],'While standardized test scores are not compulsory, they are highly recommended.')])], 'Added 2027 English scores, test variants and documented waiver; kept school-qualification obligations separate from recommended SAT.', ['IELTS section minima are not stated in Appendix 1; individual major recommendations and school-equivalence review remain applicant-specific.'])

record('meiji-university',[route(id='sgjs-english-track',label=L('School of Global Japanese Studies English Track — Nakano','School of Global Japanese Studies English Track — Nakano'),programmeIds=['social-sciences','humanities'],applicability={**cycle('September 2027',[2027]),'intakes':['fall-2027']},english={'requirement':'required-unless-exempt','ielts':score(6,'IELTS Academic in-centre paper/computer'),'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':80},{'period':'post2026','min':4}]},'alternatives':L('Cambridge 169; ACT English 18; specified old-paper SAT reading/writing scores. Digital SAT is accepted academically but NOT as English proof. IELTS Online/One Skill Retake and TOEFL Home/MyBest are not accepted.','Cambridge 169; ACT English 18; указанные баллы прежнего бумажного SAT по чтению/письму. Digital SAT принимается академически, но НЕ как подтверждение английского. IELTS Online/One Skill Retake и TOEFL Home/MyBest не принимаются.'),'waiver':L('No waivers: English-medium primary and secondary schooling does not remove the official English-score requirement.','Освобождений нет: начальная и средняя школа на английском не отменяют официальный языковой результат.')},academic={'satPolicy':'required-alternatives','note':L('One of SAT (including digital), ACT, IB Diploma or the specified EJU Japan and the World in English is required. A levels, Abitur and French/European Baccalaureate do not substitute for this examination requirement.','Обязателен один из SAT (включая digital), ACT, IB Diploma либо указанного EJU Japan and the World на английском. A levels, Abitur и французский/европейский Baccalaureate этот экзамен не заменяют.')},sources=[pdf('https://www.meiji.ac.jp/cip/english/undergraduate/nippon/englishtrack/glqts00000002hta-att/a1793259032270.pdf','Meiji SGJS English Track September 2027 guide','Meiji SGJS English Track: руководство сентября 2027',[4,8,9],'All applicants must submit the official score report of one of the following examinations.')])], 'Separated language and academic alternatives, including different digital-SAT acceptance and the explicit no-waiver rule.', ['IELTS section minima are not stated; other Meiji schools and the Japanese Track are separate.'])

record('tohoku-university',[route(id='gateway-term-ii',label=L('Gateway College Term II — October 2027','Gateway College Term II — октябрь 2027'),applicability=fall(),english={'requirement':'required-unless-exempt','ielts':score(6,'IELTS Academic / IELTS Online'),'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':80},{'period':'post2026','min':4}]},'alternatives':L('Duolingo 110; Cambridge B2/C1/C2 169; EIKEN Pre-1/1 with 2400. No IELTS Indicator/One Skill Retake, TOEFL MyBest/ITP or TOEIC.','Duolingo 110; Cambridge B2/C1/C2 169; EIKEN Pre-1/1 с 2400. IELTS Indicator/One Skill Retake, TOEFL MyBest/ITP и TOEIC не принимаются.'),'waiver':L('Three formal English-medium education years within the four academic years preceding school graduation; submit Tohoku’s designated certificate, not a generic school MOI letter.','Три года формального обучения на английском в четырёх учебных годах перед выпуском из школы; нужна форма Tohoku, а не обычное школьное письмо MOI.')},academic={'satPolicy':'required-alternatives','note':L('Required subjects must be covered by an accepted SAT/ACT/AP/EJU, IB or A-level qualification, according to Humanities/Social Sciences or STEM track; then online written examination and interview. Expected academic test scores are not hard minimums.','Обязательные предметы подтверждаются принимаемыми SAT/ACT/AP/EJU, IB либо A-level по треку Humanities/Social Sciences или STEM; далее онлайн письменный экзамен и интервью. Ожидаемые академические баллы не являются жёсткими минимумами.')},note=L('FGL undergraduate admission ended in 2026. This verified 2027 route is Gateway College, not a continuation of the old FGL admission rules.','Бакалаврский приём FGL завершился в 2026. Проверенный маршрут 2027 — Gateway College, а не продолжение прежних правил FGL.'),sources=[pdf('https://admissions.tohoku.ac.jp/en/adcms/wp-content/uploads/2026/08/ApplicationGuideGWC2027Fall.pdf','Tohoku Gateway College Fall 2027 guide','Tohoku Gateway College: руководство Fall 2027',[1,6,7,8,9,10,11,12,13,14,22],'Regardless of nationality, all applicants are required to submit a proof of English proficiency.'),S('https://www.insc.tohoku.ac.jp/english/degree/undergraduate-english/',L('Tohoku: Gateway College replaces undergraduate FGL','Tohoku: Gateway College заменяет бакалаврский FGL'))])], 'Replaced the obsolete FGL requirements context with confirmed Gateway College 2027 requirements.', ['Exact track subjects and acceptable school qualification must be checked; Japanese-taught general admission is a separate route.'])

record('okayama-university',[route(id='discovery-october',label=L('Discovery Program for Global Learners — October intake','Discovery Program for Global Learners — октябрьский набор'),applicability=fall(),english={'requirement':'required-unless-exempt','ielts':score(None,noMinimum=True),'toefl':{'accepted':True,'noMinimum':True},'alternatives':L('Cambridge, EIKEN, GTEC, TEAP, TOEFL iBT, paired TOEIC L&R plus S&W, or IB English including predicted results. No at-home tests. CEFR B2 is recommended, not a minimum score.','Cambridge, EIKEN, GTEC, TEAP, TOEFL iBT, TOEIC L&R вместе с S&W либо IB English, включая прогнозные результаты. Домашние тесты не принимаются. CEFR B2 рекомендуется, а не является балльным минимумом.'),'waiver':L('At least five years of secondary education in English. English ability is also assessed through statements and interview.','Минимум пять школьных лет на английском. Английский также оценивается по личным заявлениям и интервью.')},academic={'satPolicy':'optional','note':L('The 2027 international application instructions explicitly label SAT/ACT, national exams and EJU results optional. Eligibility and academic records remain required.','Международная инструкция 2027 прямо называет результаты SAT/ACT, национальных экзаменов и EJU необязательными. Допуск и академические документы остаются обязательными.')},localLanguage=[{'name':'Japanese','requirement':L('Japanese proof is optional for application. Access to other faculties’ courses may require Japanese assessed at interview. April orientation is in Japanese; do not apply October language context to that route.','Подтверждение японского для заявки необязательно. Для предметов других факультетов могут проверить японский на интервью. Апрельская ориентация идёт на японском; октябрьский контекст на этот маршрут не переносится.')}],sources=[S('https://discovery.okayama-u.ac.jp/en/prospective_students/admission/international-application/',L('Okayama Discovery 2027 international application instructions','Okayama Discovery: международная заявка 2027'))])], 'Recorded explicit absence of numeric language cutoffs, actual alternatives, five-year waiver and optional academic tests.', ['IELTS variant, detailed programme choices and Japanese access requirements for individual faculties require the guide/course confirmation.'])

record('institute-of-science-tokyo',[route(id='gsep-april',label=L('Global Scientists and Engineers Program (GSEP) — April 2027','Global Scientists and Engineers Program (GSEP) — апрель 2027'),programmeIds=['engineering'],applicability={**cycle('April 2027',[2027]),'intakes':['spring-2027']},english={'requirement':'required-unless-exempt','ielts':score(None,'IELTS Academic paper/computer in-centre',noMinimum=True),'toefl':{'accepted':True,'noMinimum':True},'alternatives':L('TOEFL iBT/Home Edition or TOEIC L&R. IELTS Online, institutional TOEFL/TOEIC and TOEIC S&W/Speaking/Bridge are not accepted. Two-year validity.','TOEFL iBT/Home Edition либо TOEIC L&R. IELTS Online, институциональные TOEFL/TOEIC и TOEIC S&W/Speaking/Bridge не принимаются. Срок два года.'),'waiver':L('Only nationals of the listed native-English countries with the designated document. English-medium high school alone does not qualify.','Только граждане перечисленных англоязычных стран с установленным документом. Одной школы на английском недостаточно.')},academic={'satPolicy':'optional','note':L('EJU, A-level, IB, SAT, ACT and AP are encouraged optional interview reference materials, not mandatory SAT. GSEP’s own selection and academic qualifications remain separate.','EJU, A-level, IB, SAT, ACT и AP рекомендуются как необязательные материалы для интервью, а не обязательный SAT. Собственный отбор GSEP и академическая квалификация — отдельно.')},sources=[S('https://admissions.isct.ac.jp/en/013/undergraduate/programs/gsep',L('Science Tokyo GSEP April 2027 requirements','Science Tokyo GSEP: требования апреля 2027'))])], 'Established no numeric English minimum and a nationality-limited waiver; scoped GSEP to April rather than Fall.', ['Fall 2027 GSEP entry is not established by this April guide; precise second-stage subject examinations need the full programme guide.'])
finish()
